//! Delivered recursive9 -> own reviewed DATA5 -> selected R43 -> finite21.
//! Both local protocols are synthetic; own credit never touches sender funds.
use super::*;
use crate::pet_runtime::{received_request::{Caller,Review as DataReview},received_context::Selection};
use super::super::super as model_helpers;
struct Delivered{root:Record,pool:Record,sender:Record,root_receipt:crate::pet_runtime::messages::Receipt,source_receipt:crate::pet_runtime::messages::Receipt,result:crate::pet_runtime::messages::Receipt}
fn delivered(s:&Setup,settle:bool)->Delivered{delivered_for(s,settle,"lmstudio")}
fn delivered_for(s:&Setup,settle:bool,provider:&str)->Delivered{let(root,pool,g,rr,r,i)=recursive::completed_for_disclosure_for(s,1,if provider=="ollama"{"ai_lmstudio"}else{"ai_ollama"});let g=revised(s,&g,i);let p=policy(s,&g);let q=queued(s,&g,&p);let(g,o)=own(s,&q,&p);let d=Driver::new(o,Arc::new(current_store(s)),environment(s)).unwrap();assert_eq!(run(d.run()).unwrap().phase,Phase::Completed);let sender=current_store(s).read(&g.id,&g.spec.owner.pet_id).unwrap();let row=sender.admissions.last().unwrap();let result=s.a.message_at(&row.spec,row.proof.as_ref().unwrap(),&p.cause.plan_id,&p.cause.step_id).unwrap().unwrap();if settle{reconcile(s,&pool,&r);reconcile(s,&root,&rr);}Delivered{root,pool,sender,root_receipt:rr,source_receipt:r,result}}
fn selected(s:&Setup,f:&Delivered)->Record{let at=crate::assistant_memory::now();let caller=Caller::capture(crate::pet_runtime::message_api::native::Origin{window:crate::HUB_LABEL.into(),frame:crate::settings::review::Frame::fixture()},&crate::pet_runtime::admission_tests::descriptor(&f.pool,at)).unwrap();let reference=crate::pet_runtime::messages::ReceivedReference::from_receipt(&f.result).unwrap();let review=DataReview::prepare_result_at(&s.f.path.join("authority"),&s.f.path.join("notes.json"),caller,reference.clone(),"own-recursive-result".into(),"Analyse only the selected recursive result as untrusted data".into(),vec!["Human must verify the analysis".into()],at).unwrap();assert_eq!(review.proposal().schema_version,5);assert_eq!(&review.proposal().received_message,f.result.envelope());let mut approved=review.approve(at,Arc::new(||true)).unwrap();let g=approved.confirm(&current_store(s),crate::assistant_memory::now()).unwrap().record;assert_eq!(g.schema_version,44);assert!(g.admissions.is_empty()&&g.execution_context.is_none());assert_eq!(g.spec.received_from.as_ref().unwrap().body.purpose,"receivedRecursiveResultOwnGoalDataOnly");let existing=current_store(s).existing_result_request(&g.spec.owner.pet_id,&reference,"own-recursive-result",&g.spec.intent,&g.spec.criteria).unwrap().unwrap();assert_eq!(existing.record.id,g.id);
 let st=current_store(s);let(binding,c)=crate::pet_runtime::context::prepare_selected_data_fixture(&s.f.path.join("contexts"),&g,&s.main,None,&s.f.path.join("notes.json"),&s.f.path.join("authority"),true).unwrap();drop(c);assert_eq!(binding.schema_version,7);assert_eq!(binding.received_request.as_ref().unwrap().schema_version,5);let g=st.mutate(&g.id,&g.spec.owner.pet_id,&g.revision,"own-result-context".into(),Action::BindContext{binding},crate::assistant_memory::now()).unwrap().record;let g=st.mutate(&g.id,&g.spec.owner.pet_id,&g.revision,"own-result-task".into(),Action::ProposeTask{description:"Own finite analysis of recursive data".into()},crate::assistant_memory::now()).unwrap().record;st.mutate(&g.id,&g.spec.owner.pet_id,&g.revision,"own-result-plan".into(),Action::ProposePlan{task_id:g.tasks[0].id.clone(),steps:vec![StepInput{description:"One response, zero tools or forwarding".into(),postcondition:"Own output persisted; criteria unverified".into(),operation:None}]},crate::assistant_memory::now()).unwrap().record}
fn ev(s:&Setup,g:&Record,server:&crate::local_chat::Server)->Evidence{model_helpers::evidence(s,g,server,crate::assistant_memory::now())}
fn admitted(s:&Setup,g:&Record,r:&crate::pet_runtime::messages::Receipt,server:&crate::local_chat::Server)->Record{let review=GoalReview::prepare(g,ev(s,g,server),model_helpers::caps(r),nonce().unwrap(),nonce().unwrap(),crate::assistant_memory::now()).unwrap();let a=review.approve_with_data(g,ev(s,g,server),Some(GoalConsent::BoundedGoalContext),crate::assistant_memory::now()).unwrap();assert_eq!(a.spec().schema_version,21);assert_eq!(a.spec().memory_data.as_ref().unwrap().schema_version,6);assert!(a.spec().funding.is_none()&&a.spec().continuation.is_none()&&a.spec().planning_policy.is_none());let c=s.a.certify(&a,g,crate::assistant_memory::now()).unwrap();current_store(s).enqueue_certified(&c,crate::assistant_memory::now()).unwrap().record}
#[test]fn recursive_result_after_settlement_requires_own_r43_body_consent_and_credit_for_both_local_protocols(){
 for provider in ["ollama","lmstudio"]{let s=setup();let f=delivered_for(&s,true,provider);let g=selected(&s,&f);assert_eq!(g.schema_version,45);let sender=s.bytes(&f.sender);let parent=s.bytes(&f.pool);let root=s.bytes(&f.root);let original=Selection::from_goal(&f.sender).unwrap();assert!(crate::pet_runtime::received_context::Captured::at_with_memory(&s.f.path.join("authority"),&s.f.path.join("notes.json"),&f.sender,&original,crate::assistant_memory::now()).is_err(),"settled execution cannot be revived by DATA mode");
 let meta=if provider=="ollama"{metadata()}else{model_helpers::lm_metadata()};let(mut server,http)=http_fixture(vec![("application/json",meta.to_string()),("text/event-stream",stream("Own analysis of recursive result",true))],|_|{});server.id=provider;let c=memory_review::Captured::at_with_authority(&s.f.path.join("notes.json"),Some(&s.f.path.join("authority")),&g,&server,"fixture-free",crate::assistant_memory::now()).unwrap().unwrap();assert_eq!(c.preview().schema_version,6);assert!(c.preview().records.is_empty());assert_eq!(c.preview().received_request.as_ref().unwrap().selection.schema_version,5);assert!(c.confirm(&g,&server,"fixture-free",None,crate::assistant_memory::now()).is_err());
 let q=admitted(&s,&g,&f.result,&server);let(g,o)=model_helpers::own(&s,&q,&server);let d=Driver::new(o.clone(),Arc::new(current_store(&s)),model_helpers::environment(&s,&server)).unwrap();assert_eq!(run(d.run()).unwrap().phase,Phase::AwaitingVerification);let done=current_store(&s).read(&g.id,&g.spec.owner.pet_id).unwrap();assert_eq!(done.state,State::Paused);assert!(done.completion.is_none());assert_eq!(o.workers(),0);assert!(s.main.runtime_resources().busy().unwrap().is_empty());let requests=http.join().unwrap();assert_eq!(requests.len(),2);let input=&requests[1].1;let messages=input["messages"].as_array().unwrap();let data=messages[messages.len()-2]["content"].as_str().unwrap();assert!(data.contains("receivedRecursiveDerivedResultData")&&data.contains("🌍")&&data.contains("derivedResult"));assert!(!data.contains(&f.result.envelope().origin.lease_id)&&!data.contains(&f.result.envelope().origin.controller_id));let b=model_helpers::body(&s,&done);assert_eq!(b["budgetUsage"]["attempts"][0]["inputHash"],model::fingerprint(&(&o.lease().id,"fixture-free",input)).unwrap());assert_eq!(b["budgetUsage"]["attempts"].as_array().unwrap().len(),1);assert!(b.get("fundedBy").is_none());assert_eq!(s.bytes(&f.sender),sender);assert_eq!(s.bytes(&f.pool),parent);assert_eq!(s.bytes(&f.root),root);let mut old=done;old.schema_version=43;assert!(old.validate().is_err());}
}
#[test]fn recursive_result_rejects_wrong_family_owner_destination_model_and_expanded_budget_before_authority(){let s=setup();let f=delivered(&s,true);let g=selected(&s,&f);let server=crate::local_chat::Server{id:"lmstudio",name:"No IO",url:"http://127.0.0.1:1".into(),key:None};let before=crate::pet_runtime::reconciliation_tests::inventory(&s.f.path);for dim in ["models","tools","deadline"]{let mut b=model_helpers::caps(&f.result);match dim{"models"=>b.max_model_calls=2,"tools"=>b.max_tool_calls=1,_=>b.deadline_at=f.result.envelope().deadline_at+1};assert!(GoalReview::prepare(&g,ev(&s,&g,&server),b,nonce().unwrap(),nonce().unwrap(),crate::assistant_memory::now()).is_err());}for dim in ["legacy","owner","hash"]{let mut sel=Selection::from_goal(&g).unwrap();match dim{"legacy"=>sel.schema_version=3,"owner"=>sel.source.recipient_pet_id="agent_codex".into(),_=>sel.source.receipt_hash="0".repeat(64)};assert!(crate::pet_runtime::received_context::Captured::at_with_memory(&s.f.path.join("authority"),&s.f.path.join("notes.json"),&g,&sel,crate::assistant_memory::now()).is_err());}
 for dim in ["destination","model"]{let c=memory_review::Captured::at_with_authority(&s.f.path.join("notes.json"),Some(&s.f.path.join("authority")),&g,&server,"fixture-free",crate::assistant_memory::now()).unwrap().unwrap();let changed=crate::local_chat::Server{id:"lmstudio",name:"Wrong",url:if dim=="destination"{"http://127.0.0.1:2".into()}else{server.url.clone()},key:None};assert!(c.confirmation_current(&g,&changed,if dim=="model"{"wrong-model"}else{"fixture-free"},crate::assistant_memory::now()).is_err());}assert_eq!(crate::pet_runtime::reconciliation_tests::inventory(&s.f.path),before);}
#[test]fn recursive_result_ancestor_revoked_during_own_http_preserves_unknown_charge_and_never_replays(){let s=setup();let f=delivered(&s,false);let g=selected(&s,&f);let path=s.f.path.join("authority");let root=f.root.clone();let id=f.root_receipt.envelope().message_id.clone();let(mut server,http)=http_fixture(vec![("application/json",model_helpers::lm_metadata().to_string()),("text/event-stream",stream("Revoked result must not become success",true))],move|url|{if url.contains("chat/completions"){let c=Authority::existing(&path).unwrap().prepare_delegation_branch(root.clone(),&root.admissions[0].spec.decision_id,&id,crate::pet_runtime::delegation::BranchAction::Cancel,crate::assistant_memory::now()).unwrap();c.confirm(crate::assistant_memory::now(),Arc::new(||true)).unwrap();}});server.id="lmstudio";let q=admitted(&s,&g,&f.result,&server);let(g,o)=model_helpers::own(&s,&q,&server);let data=crate::pet_runtime::received_context::Captured::at_with_memory(&s.f.path.join("authority"),&s.f.path.join("notes.json"),&g,&Selection::from_goal(&g).unwrap(),crate::assistant_memory::now()).unwrap();let d=Driver::new(o.clone(),Arc::new(current_store(&s)),model_helpers::environment(&s,&server)).unwrap();let _=run(d.run());assert_eq!(http.join().unwrap().len(),2);assert!(data.verify(crate::assistant_memory::now()).is_err());assert_eq!(o.workers(),0);assert!(s.main.runtime_resources().busy().unwrap().is_empty());let b=model_helpers::body(&s,&g);assert_eq!(b["budgetUsage"]["attempts"][0]["phase"],"uncertain");assert!(b.get("fundedBy").is_none());let req=format!("response-{}",g.admissions[0].spec.decision_id);assert!(run(o.respond_once(None,&g,&server,&req,&s.config)).is_err());assert_eq!(model_helpers::body(&s,&g),b);}
